import hashlib,struct,sys,zlib
sys.path.insert(0,'/workspace/project')
from wire import packet,emissions,MASK

def run(c):
    kind=c['primitive']; K=c['segments']; N=c['capacity']; D=c['words']; root=c['root']; base=c['start']
    req={root} if kind=='broadcast' else set(range(4))
    slots={}; R=[0]*4; S=[0]*4; A=[0]*4; U=[0]*4; repeat=[False]*4
    b=0; counters=[0]*14; budget=-1; tape=hashlib.sha256(); packets=0; bytes_=0; snaps=[]; trace=[]
    # Build an explicit mapping, independent from closed-form prefixes.
    outs=[{} for r in range(4)]; deps={}
    for p in range(K):
        for r in req:deps[p,r]=[]
        if kind in ['allreduce','reduce','barrier','reducescatter']:
            dests=[root] if kind=='reduce' else [p//(K//4)] if kind=='reducescatter' else range(4)
            for d in dests:
                q=p%(K//4) if kind=='reducescatter' else p
                outs[d][q]=(p,None)
                for r in req:
                    if kind not in ['allreduce','barrier'] or r==d: deps[p,r].append((d,q))
        elif kind=='broadcast':
            for d in range(4):
                if d!=root:
                    outs[d][p]=(p,root);deps[p,root].append((d,p))
        else:
            for d in range(4):
                for i,r in enumerate(s for s in range(4) if s!=d):
                    q=3*p+i;outs[d][q]=(p,r);deps[p,r].append((d,q))
    def all_acked(p):
        return all(A[d]>q for d in range(4) for q,(ip,src) in outs[d].items() if ip==p)
    def eligible(r):
        for p in range(R[r]):
            if c['mode']==2 and not all(A[d]>q for d,q in deps[p,r]):return p
        return R[r]
    def send(d,prefix=None,q=None):
        nonlocal budget,packets,bytes_
        if budget==0:
            counters[11]+=1;return False
        if budget>0:budget-=1
        if prefix is not None:
            f=packet(d,(base+prefix-1)&MASK,ack=True,outgoing=True);counters[3]+=1
        else:
            p,s=outs[d][q]; values=slots[p]
            if kind in ['allgather','broadcast']:payload=values[s]
            else:
                payload=struct.pack('!%dI'%D,*(sum(struct.unpack('!%dI'%D,v)[j] for v in values.values())&0xffffffff for j in range(D)))
            f=packet(d,(base+q)&MASK,payload,outgoing=True);counters[2]+=1
