        if len(trace)<c.get('trace',0):trace.append({'rank':d,'hex':f.hex()})
        return True
    def service(retry=None):
        nonlocal b
        def work():
            for r in range(4):
                e=eligible(r)
                if e>0 and (e>U[r] or repeat[r]):
                    if not send(r,prefix=e):return
                    U[r]=e;repeat[r]=False
            if retry is not None:
                for q in range(A[retry],S[retry]):
                    if not send(retry,q=q):return
            for d in range(4):
                while S[d] in outs[d]:
                    q=S[d]; p,s=outs[d][q]
                    if p not in slots or set(slots[p])!=req:break
                    if not send(d,q=q):return
                    S[d]+=1
