        if len(f)<58:return False,False,None,None,None
        try:
            if f[12:15]!=b'\x08\x00\x45' or f[23]!=17 or int.from_bytes(f[16:18],'big')+14!=len(f) or f[20:22] not in [b'\0\0',b'\x40\0']:raise ValueError()
