                if f[50]!=128 or len(f)!=58+4*D:raise ValueError()
            else:
                if f[42]!=17 or f[50]!=0 or len(f)!=62 or int.from_bytes(f[54:58],'big') != 0x1f000000|((int.from_bytes(f[51:54],'big')+1)&MASK):raise ValueError()
            crc=bytearray(b'\xff'*8+f[14:-4]);crc[9]=255;crc[16]=255;crc[18:20]=b'\xff\xff';crc[34:36]=b'\xff\xff';crc[40]=255
            if int.from_bytes(f[-4:],'little')!=zlib.crc32(crc):raise ValueError()
        except ValueError:return False,False,None,None,None
