        endpoint=(f[:6]==bytes([2,1,0,0,0,r+1]) and f[6:12]==bytes([2,0,0,0,0,r+1]) and f[26:30]==bytes([10,0,0,r+1]) and f[30:34]==bytes([10,0,0,101+r]) and int.from_bytes(f[46:50],'big')==512+r and (not isdata or (p<K and r in req)))
        return True,endpoint,isdata,p,f[54:-4]
