            good,endpoint,isdata,p,payload=decode(arg,f)
            if not good:counters[8]+=1;continue
            if not endpoint:counters[9]+=1;continue
            if isdata:
                counters[0]+=1
                if p<b:counters[7]+=1;repeat[arg]=True
                elif p>=b+N:counters[6]+=1
                elif arg in slots.get(p,{}):counters[5]+=1;repeat[arg]=True
                else:
